sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
uniform float slices;
float hash(float n) { return fract(sin(n * 91.3458 + 47.123) * 43758.5453); }
half4 main(float2 xy) {
    float k = strength * beat;
    if (k < 0.001) return image.eval(xy);
    float row = floor(xy.y / max(size.y, 1.0) * max(slices, 1.0));
    float seed = row * 7.31 + beatIndex * 13.7 + floor(beatTime * 20.0) * 3.1;
    float shift = (hash(seed + 1.7) - 0.5) * 0.3 * size.x * k * step(0.55, hash(seed));
    float2 q = xy + float2(shift, 0.0);
    float2 split = float2(0.012 * size.x * k, 0.0);
    half4 g = image.eval(q);
    half4 r = image.eval(q + split);
    half4 b = image.eval(q - split);
    return half4(r.r, g.g, b.b, max(max(r.a, g.a), b.a));
}
